            runOnEdt(swingTask);
        }
        StorageIndex activeNextAccountIndex = controller.activeIndexOrNull();
        int persistedBeforeOldTask = persistenceWrites.get();
        int nextAccountSize = activeNextAccountIndex.items().size();
