    {
        BankItemMetadata unknownWieldable = new BankItemMetadata(
            "New weapon", false, true, false, false, -1, 0, 0, 0, 0, 0, 0, 0, 0f, 0);

        assertTrue(classifier.matches("weapons", unknownWieldable));
    }

    @Test
