package com.semanticbanksearch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

public class SemanticRule
{
    private static final Set<String> RAW_FOOD_PATTERN_EXCLUSIONS = Set.of(
        "shark",
        "karambwan",
        "manta ray",
        "anglerfish",
        "sea turtle",
        "monkfish",
        "trout",
        "salmon",
        "lobster",
        "swordfish",
        "dark crab");

    private static final Set<String> GENERIC_CATEGORY_WORDS = Set.of(
        "weapon",
        "weapons",
        "tool",
        "tools",
        "utility",
        "supplies",
        "protection",
        "prep",
        "restoration",
        "slayer",
        "task",
        "run",
        "devil",
        "clue",
        "desert",
        "skilling",
        "boost",
        "boosts",
        "runes");

    private final String category;
    private final String reason;
    private final List<String> queryAliases;
    private final List<String> itemNamePatterns;
    private final Map<String, Integer> foodScores;
    private final int baseScore;

    public SemanticRule(
        String category,
        String reason,
        List<String> queryAliases,
        List<String> itemNamePatterns,
        Map<String, Integer> foodScores,
        int baseScore)
    {
        this.category = normalizeString(category);
        this.reason = normalizeString(reason);
        this.queryAliases = normalizeList(queryAliases);
        this.itemNamePatterns = normalizeList(itemNamePatterns);
        this.foodScores = normalizeScores(foodScores);
        this.baseScore = baseScore;
    }

    public String getCategory()
    {
        return category;
    }

    public String getReason()
    {
        return reason;
    }

    public boolean matchesQuery(String normalizedQuery)
    {
        if (normalizedQuery == null || normalizedQuery.trim().isEmpty())
        {
            return false;
        }

        for (String alias : queryAliases)
        {
            if (matchesAlias(normalizedQuery, alias))
            {
                return true;
            }
        }

        for (String categoryWord : normalizedCategoryWords())
        {
            if (containsWord(normalizedQuery, categoryWord))
            {
                return true;
            }
        }

        return false;
    }

    public boolean matchesItem(String normalizedItemName)
    {
        if (normalizedItemName == null || normalizedItemName.trim().isEmpty())
        {
            return false;
        }

        for (String pattern : itemNamePatterns)
        {
            if (isRawFoodMatchForCookedFoodPattern(normalizedItemName, pattern))
            {
                continue;
            }
            if (normalizedItemName.contains(pattern))
            {
                return true;
            }
        }

        return false;
    }

    boolean matchesObservedItem(ObservedItem item)
    {
        if (item == null)
        {
            return false;
        }
        return matchesItem(SemanticSearchEngine.normalize(item.getName()));
    }

    public int scoreFor(String normalizedItemName)
    {
        int score = baseScore;
        for (Map.Entry<String, Integer> entry : foodScores.entrySet())
        {
            if (normalizedItemName.contains(entry.getKey()))
            {
                score = Math.max(score, baseScore + entry.getValue());
            }
        }
        return score;
    }

    private static boolean isRawFoodMatchForCookedFoodPattern(String normalizedItemName, String pattern)
    {
        return normalizedItemName.startsWith("raw ") && RAW_FOOD_PATTERN_EXCLUSIONS.contains(pattern);
    }

    private List<String> normalizedCategoryWords()
    {
        String normalizedCategory = category.toLowerCase(Locale.ROOT);
        List<String> words = new ArrayList<>();
        for (String word : normalizedCategory.split("\\s+"))
        {
            if (word.length() > 2 && !GENERIC_CATEGORY_WORDS.contains(word))
            {
                words.add(word);
            }
        }
        return words;
    }

    private static boolean matchesAlias(String normalizedQuery, String normalizedAlias)
    {
        if (normalizedAlias == null || normalizedAlias.isEmpty())
        {
            return false;
        }
        if (!normalizedAlias.contains(" ") && GENERIC_CATEGORY_WORDS.contains(normalizedAlias))
        {
            return normalizedQuery.equals(normalizedAlias);
        }
        return FuzzyMatcher.phraseMatches(normalizedQuery, normalizedAlias);
    }

    private static boolean containsWord(String normalizedText, String normalizedWord)
    {
        for (String token : normalizedText.split("\\s+"))
        {
            if (token.equals(normalizedWord) || token.startsWith(normalizedWord) || normalizedWord.startsWith(token))
            {
                return true;
            }
        }
        return false;
    }

    private static List<String> normalizeList(List<String> values)
    {
        if (values == null || values.isEmpty())
        {
            return Collections.emptyList();
        }

        List<String> normalized = new ArrayList<>();
        for (String value : values)
        {
            String normalizedValue = SemanticSearchEngine.normalize(value);
            if (!normalizedValue.isEmpty())
            {
                normalized.add(normalizedValue);
            }
        }
        return Collections.unmodifiableList(normalized);
    }

    private static Map<String, Integer> normalizeScores(Map<String, Integer> values)
    {
        if (values == null || values.isEmpty())
        {
            return Collections.emptyMap();
        }

        Map<String, Integer> normalized = new LinkedHashMap<>();
        for (Map.Entry<String, Integer> entry : values.entrySet())
        {
            String key = SemanticSearchEngine.normalize(entry.getKey());
            if (!key.isEmpty() && entry.getValue() != null)
            {
                normalized.put(key, entry.getValue());
            }
        }
        return Collections.unmodifiableMap(normalized);
    }

    private static String normalizeString(String value)
    {
        return value == null ? "" : value.trim();
    }
}

package com.semanticbanksearch;

import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class ConsumableSemanticClassifier
{
    private enum QueryType
    {
        NONE,
        FOOD,
        POTION,
        COMBO_FOOD,
        FULL_POTION,
        LOW_DOSE_POTION
    }

    private static final Set<String> FOOD_QUERIES = Set.of(
        "food", "foods", "eats", "edible", "edibles", "healing food", "food i own", "all food");
    private static final Set<String> POTION_QUERIES = Set.of(
        "potion", "potions", "pot", "pots", "all potions", "all pots");
    private static final Set<String> COMBO_FOOD_QUERIES = Set.of(
        "combo food", "combo foods", "combo eats", "fast combo food");
    private static final Set<String> FULL_POTION_QUERIES = Set.of(
        "full potions", "full pots", "4 dose potion", "4 dose potions", "4 dose pot", "4 dose pots");
    private static final Set<String> LOW_DOSE_POTION_QUERIES = Set.of(
        "low dose potions", "low dose pots", "1 dose potions", "1 dose pots", "2 dose potions", "2 dose pots");
    private static final Set<String> COMBO_FOOD_NAMES = Set.of(
        "cooked karambwan", "karambwan");
    private static final Pattern DOSE_SUFFIX = Pattern.compile("\\(([1-4])\\)$");

    boolean recognizes(String query)
    {
        return queryType(query) != QueryType.NONE;
    }

    boolean matches(String query, BankItemMetadata item)
    {
        if (item == null)
        {
            return false;
        }

        switch (queryType(query))
        {
            case FOOD:
                return item.isEdible();
            case POTION:
                return isPotion(item);
            case COMBO_FOOD:
                return item.isEdible() && COMBO_FOOD_NAMES.contains(normalizedBaseName(item.getName()));
            case FULL_POTION:
                return isPotion(item) && dose(item.getName()) == 4;
            case LOW_DOSE_POTION:
                int dose = dose(item.getName());
                return isPotion(item) && dose > 0 && dose <= 2;
            default:
                return false;
        }
    }

    private static boolean isPotion(BankItemMetadata item)
    {
        if (!item.isDrinkable())
        {
            return false;
        }

        String name = SemanticSearchEngine.normalize(item.getName());
        return name.contains("potion")
            || name.contains("brew")
            || name.contains("restore")
            || name.contains("serum")
            || name.contains("antipoison")
            || name.contains("anti venom")
            || name.contains("antidote")
            || name.contains("mix");
    }

    private static int dose(String itemName)
    {
        Matcher matcher = DOSE_SUFFIX.matcher(itemName == null ? "" : itemName.trim());
        return matcher.find() ? Integer.parseInt(matcher.group(1)) : 0;
    }

    private static String normalizedBaseName(String itemName)
    {
        return SemanticSearchEngine.normalize(
            itemName == null ? "" : itemName.replaceFirst("\\([1-4]\\)$", ""));
    }

    private static QueryType queryType(String query)
    {
        String normalized = SemanticSearchEngine.normalize(query);
        if (FOOD_QUERIES.contains(normalized))
        {
            return QueryType.FOOD;
        }
        if (POTION_QUERIES.contains(normalized))
        {
            return QueryType.POTION;
        }
        if (COMBO_FOOD_QUERIES.contains(normalized))
        {
            return QueryType.COMBO_FOOD;
        }
        if (FULL_POTION_QUERIES.contains(normalized))
        {
            return QueryType.FULL_POTION;
        }
        if (LOW_DOSE_POTION_QUERIES.contains(normalized))
        {
            return QueryType.LOW_DOSE_POTION;
        }
        return QueryType.NONE;
    }
}

