package com.semanticbanksearch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class ReadinessPack
{
    private final String name;
    private final String description;
    private final List<String> aliases;
    private final List<ReadinessSlot> slots;

    public ReadinessPack(String name, String description, List<String> aliases, List<ReadinessSlot> slots)
    {
        this.name = clean(name);
        this.description = clean(description);
        this.aliases = normalizeAliases(aliases);
        this.slots = copySlots(slots);
    }

    public String getName()
    {
        return name;
    }

    public String getDescription()
    {
        return description;
    }

    public List<ReadinessSlot> getSlots()
    {
        return slots;
    }

    public boolean matches(String normalizedQuery)
    {
        if (normalizedQuery == null || normalizedQuery.isEmpty())
        {
            return false;
        }
        for (String alias : aliases)
        {
            if (FuzzyMatcher.phraseMatches(normalizedQuery, alias))
            {
                return true;
            }
        }
        return false;
    }

    private static List<String> normalizeAliases(List<String> values)
    {
        if (values == null || values.isEmpty())
        {
            return Collections.emptyList();
        }
        List<String> aliases = new ArrayList<>();
        for (String value : values)
        {
            String normalized = SemanticSearchEngine.normalize(value);
            if (!normalized.isEmpty())
            {
                aliases.add(normalized);
            }
        }
        return Collections.unmodifiableList(aliases);
    }

    private static List<ReadinessSlot> copySlots(List<ReadinessSlot> values)
    {
        if (values == null || values.isEmpty())
        {
            return Collections.emptyList();
        }
        return Collections.unmodifiableList(new ArrayList<>(values));
    }

    private static String clean(String value)
    {
        return value == null ? "" : value.trim();
    }
}

package com.semanticbanksearch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class SemanticBankQueryParser
{
    List<String> parse(String query)
    {
        String normalized = SemanticSearchEngine.normalize(query);
        if (normalized.isEmpty())
        {
            return Collections.emptyList();
        }

        List<String> clauses = new ArrayList<>();
        addPotionDoseClause(normalized, clauses);
        addCombatStyleClause(normalized, clauses);
        addPrayerGearClause(normalized, clauses);
        addTargetClause(normalized, clauses);
        addPotionPurposeClause(normalized, clauses);

        return clauses.size() < 2 ? Collections.emptyList() : Collections.unmodifiableList(clauses);
    }

    private static void addPotionDoseClause(String query, List<String> clauses)
    {
        if (!hasPotionWord(query))
        {
            return;
        }
        if (query.contains("4 dose") || query.contains("four dose") || query.contains("full pot"))
        {
            addUnique(clauses, "full pots");
        }
        else if (query.contains("1 dose") || query.contains("one dose")
            || query.contains("2 dose") || query.contains("two dose") || query.contains("low dose"))
        {
            addUnique(clauses, "low dose pots");
        }
    }

    private static void addCombatStyleClause(String query, List<String> clauses)
    {
        boolean weaponQuery = containsAny(query, "weapon", "weapons", "wep", "weps");
        boolean gearQuery = weaponQuery || containsAny(query, "gear", "equipment");
        if (!gearQuery)
        {
            return;
        }

        if (containsAny(query, "range", "ranged"))
        {
            addUnique(clauses, weaponQuery ? "ranged weapon" : "range gear");
        }
        else if (containsAny(query, "mage", "magic"))
        {
            addUnique(clauses, weaponQuery ? "magic weapon" : "mage gear");
        }
        else if (query.contains("melee"))
        {
            addUnique(clauses, "melee gear");
        }
    }

    private static void addPrayerGearClause(String query, List<String> clauses)
    {
        if (query.contains("prayer") && containsAny(query, "gear", "equipment", "weapon", "weapons", "wep", "weps"))
        {
            addUnique(clauses, "prayer gear");
        }
    }

    private static void addTargetClause(String query, List<String> clauses)
    {
        if (containsAny(query, "dragon", "dragons", "dragon task", "dragon slayer"))
        {
            addUnique(clauses, "dragon slayer task");
        }
        else if (containsAny(query, "demon", "demons", "demon task", "demon slayer"))
        {
            addUnique(clauses, "demon slayer task");
        }
        else if (containsAny(query, "undead", "zombie", "skeleton", "ankou"))
        {
            addUnique(clauses, "undead slayer");
        }
    }

    private static void addPotionPurposeClause(String query, List<String> clauses)
    {
        if (!hasPotionWord(query))
        {
            return;
        }

        if (containsAny(query, "prayer", "ppot", "pray"))
        {
            addUnique(clauses, "prayer restoration");
        }
        else if (containsAny(query, "stamina", "energy", "run energy"))
        {
            addUnique(clauses, "run energy");
        }
        else if (containsAny(query, "poison", "venom", "antipoison"))
        {
            addUnique(clauses, "poison protection");
        }
        else if (containsAny(query, "combat", "melee", "strength", "attack", "defence"))
        {
            addUnique(clauses, "combat boost");
        }
        else if (containsAny(query, "range", "ranged", "mage", "magic"))
        {
            addUnique(clauses, query.contains("range") ? "ranged boost" : "magic boost");
        }
    }

    private static boolean hasPotionWord(String query)
    {
        return containsAny(query, "pot", "pots", "potion", "potions", "ppot");
    }

    private static boolean containsAny(String query, String... phrases)
    {
        for (String phrase : phrases)
        {
            if (containsPhrase(query, phrase))
            {
                return true;
            }
        }
        return false;
    }

    private static boolean containsPhrase(String query, String phrase)
    {
        return (" " + query + " ").contains(" " + phrase + " ");
    }

    private static void addUnique(List<String> clauses, String clause)
    {
        if (!clauses.contains(clause))
        {
            clauses.add(clause);
        }
    }
}

package com.semanticbanksearch;

import java.util.Collections;
import java.util.List;
import java.util.Set;
import net.runelite.api.EquipmentInventorySlot;

final class RelativeRankingClassifier
{
    private enum Ranking
    {
        NONE,
        BEST_FOOD,
        GOOD_FOOD,
        BEST_PRAYER,
        BEST_MELEE,
        BEST_RANGED,
        BEST_MAGIC
    }

    private static final Set<String> BEST_FOOD_QUERIES = Set.of(
        "best food", "best food i own", "highest healing food", "most healing food", "strongest food");
    private static final Set<String> GOOD_FOOD_QUERIES = Set.of(
        "good food", "good healing food", "high healing food");
    private static final Set<String> BEST_PRAYER_QUERIES = Set.of(
        "best prayer gear", "highest prayer gear", "highest prayer bonus", "best prayer equipment");
    private static final Set<String> BEST_MELEE_QUERIES = Set.of(
        "best melee weapon", "best melee wep", "strongest melee weapon", "strongest melee wep");
    private static final Set<String> BEST_RANGED_QUERIES = Set.of(
        "best ranged weapon", "best range weapon", "best ranged wep", "strongest ranged weapon", "strongest range weapon");
    private static final Set<String> BEST_MAGIC_QUERIES = Set.of(
        "best magic weapon", "best mage weapon", "best magic wep", "strongest magic weapon", "strongest mage weapon");

    boolean recognizes(String query)
    {
        return ranking(query) != Ranking.NONE;
    }

    boolean matches(String query, BankItemMetadata candidate, List<BankItemMetadata> ownedItems)
    {
        if (candidate == null)
        {
            return false;
        }

        List<BankItemMetadata> safeItems = ownedItems == null ? Collections.emptyList() : ownedItems;
        switch (ranking(query))
        {
            case BEST_FOOD:
                return candidate.isEdible() && candidate.getHealing() >= 0
                    && candidate.getHealing() == maximum(safeItems, Ranking.BEST_FOOD, candidate);
            case GOOD_FOOD:
                int bestHealing = maximum(safeItems, Ranking.BEST_FOOD, candidate);
                return candidate.isEdible() && candidate.getHealing() >= 0 && bestHealing >= 0
                    && candidate.getHealing() * 100 >= bestHealing * 80;
            case BEST_PRAYER:
                return candidate.isEquipable() && candidate.getPrayer() > 0
                    && candidate.getPrayer() == maximum(safeItems, Ranking.BEST_PRAYER, candidate);
            case BEST_MELEE:
                return isWeapon(candidate) && candidate.meleeScore() > 0
                    && candidate.meleeScore() == maximum(safeItems, Ranking.BEST_MELEE, candidate);
            case BEST_RANGED:
                return isWeapon(candidate) && candidate.rangedScore() > 0
                    && candidate.rangedScore() == maximum(safeItems, Ranking.BEST_RANGED, candidate);
            case BEST_MAGIC:
                return isWeapon(candidate) && candidate.magicScore() > 0
                    && Math.round(candidate.magicScore()) == maximum(safeItems, Ranking.BEST_MAGIC, candidate);
            default:
                return false;
        }
    }

    String explanation(String query, BankItemMetadata item)
    {
        if (item == null)
        {
            return "";
        }
        switch (ranking(query))
        {
            case BEST_FOOD:
            case GOOD_FOOD:
                return "Heals " + item.getHealing() + " HP";
            case BEST_PRAYER:
                return "+" + item.getPrayer() + " prayer in this equipment slot";
            case BEST_MELEE:
                return "Melee score " + item.meleeScore();
            case BEST_RANGED:
                return "Ranged score " + item.rangedScore();
            case BEST_MAGIC:
                return "Magic score " + formatScore(item.magicScore());
            default:
                return "";
        }
    }

    int score(String query, BankItemMetadata item)
    {
        if (item == null)
        {
            return 0;
        }
        switch (ranking(query))
        {
            case BEST_FOOD:
            case GOOD_FOOD:
                return item.getHealing();
            case BEST_PRAYER:
                return item.getPrayer();
            case BEST_MELEE:
                return item.meleeScore();
            case BEST_RANGED:
                return item.rangedScore();
            case BEST_MAGIC:
                return Math.round(item.magicScore() * 10f);
            default:
                return 0;
        }
    }

    private static int maximum(List<BankItemMetadata> items, Ranking ranking, BankItemMetadata candidate)
    {
        int maximum = -1;
        for (BankItemMetadata item : items)
        {
            if (item == null)
            {
                continue;
            }
            if (ranking == Ranking.BEST_FOOD && item.isEdible())
            {
                maximum = Math.max(maximum, item.getHealing());
            }
            else if (ranking == Ranking.BEST_PRAYER && item.isEquipable()
                && item.getEquipmentSlot() == candidate.getEquipmentSlot())
            {
                maximum = Math.max(maximum, item.getPrayer());
            }
            else if (ranking == Ranking.BEST_MELEE && isWeapon(item))
            {
                maximum = Math.max(maximum, item.meleeScore());
            }
            else if (ranking == Ranking.BEST_RANGED && isWeapon(item))
            {
                maximum = Math.max(maximum, item.rangedScore());
            }
            else if (ranking == Ranking.BEST_MAGIC && isWeapon(item))
            {
                maximum = Math.max(maximum, Math.round(item.magicScore()));
            }
        }
        return maximum;
    }

    private static boolean isWeapon(BankItemMetadata item)
    {
        return item.getEquipmentSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx() || item.isWieldable();
    }

    private static String formatScore(float score)
    {
        return score == Math.round(score) ? Integer.toString(Math.round(score)) : Float.toString(score);
    }

    private static Ranking ranking(String query)
    {
        String normalized = SemanticSearchEngine.normalize(query);
        if (BEST_FOOD_QUERIES.contains(normalized))
        {
            return Ranking.BEST_FOOD;
        }
        if (GOOD_FOOD_QUERIES.contains(normalized))
        {
            return Ranking.GOOD_FOOD;
        }
        if (BEST_PRAYER_QUERIES.contains(normalized))
        {
            return Ranking.BEST_PRAYER;
        }
        if (BEST_MELEE_QUERIES.contains(normalized))
        {
            return Ranking.BEST_MELEE;
        }
        if (BEST_RANGED_QUERIES.contains(normalized))
        {
            return Ranking.BEST_RANGED;
        }
        if (BEST_MAGIC_QUERIES.contains(normalized))
        {
            return Ranking.BEST_MAGIC;
        }
        return Ranking.NONE;
    }
}

package com.semanticbanksearch;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

public class SemanticCoverageAnalyzer
{
    private final List<SemanticRule> rules;

    public SemanticCoverageAnalyzer(List<SemanticRule> rules)
    {
        this.rules = rules == null ? new ArrayList<>() : new ArrayList<>(rules);
    }

    public List<SemanticCoverageResult> analyze(List<ObservedItem> items)
    {
        List<SemanticCoverageResult> results = new ArrayList<>();
        if (items == null)
        {
            return results;
        }

        for (ObservedItem item : items)
        {
            if (item != null)
            {
                results.add(analyzeItem(item));
            }
        }

        results.sort(Comparator
            .comparing(SemanticCoverageResult::isCovered)
            .thenComparing(SemanticCoverageResult::getItemName, String.CASE_INSENSITIVE_ORDER)
            .thenComparing(SemanticCoverageResult::getSourceName, String.CASE_INSENSITIVE_ORDER));
        return results;
    }

    private SemanticCoverageResult analyzeItem(ObservedItem item)
    {
        Set<String> categories = new LinkedHashSet<>();
        Set<String> reasons = new LinkedHashSet<>();
        String normalizedName = SemanticSearchEngine.normalize(item.getName());
        int bestScore = 0;

        for (SemanticRule rule : rules)
        {
            if (rule.matchesObservedItem(item))
            {
                categories.add(rule.getCategory());
                reasons.add(rule.getReason());
                bestScore = Math.max(bestScore, rule.scoreFor(normalizedName));
            }
        }

        List<String> mechanicalTags = categories.isEmpty()
            ? ItemAwarenessClassifier.mechanicalTags(item)
            : new ArrayList<>();
        ItemAwarenessStatus awarenessStatus = awarenessStatus(categories, mechanicalTags, item);
        return new SemanticCoverageResult(
            item,
            new ArrayList<>(categories),
            new ArrayList<>(reasons),
            mechanicalTags,
            awarenessStatus,
            bestScore);
    }

    private static ItemAwarenessStatus awarenessStatus(Set<String> categories, List<String> mechanicalTags, ObservedItem item)
    {
        if (!categories.isEmpty())
        {
            return ItemAwarenessStatus.SEMANTIC_COVERED;
        }
        if (!mechanicalTags.isEmpty())
        {
            return ItemAwarenessStatus.MECHANICALLY_TAGGED;
        }
        if (ItemAwarenessClassifier.isKnownObservedItem(item))
        {
            return ItemAwarenessStatus.KNOWN_UNCLASSIFIED;
        }
        return ItemAwarenessStatus.UNKNOWN_OBSERVED;
    }
}

package com.semanticbanksearch;

import java.util.Objects;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;

final class ThreadBridge
{
    private final Consumer<Runnable> clientExecutor;
    private final Consumer<Runnable> swingExecutor;

    ThreadBridge(Consumer<Runnable> clientExecutor, Consumer<Runnable> swingExecutor)
    {
        this.clientExecutor = Objects.requireNonNull(clientExecutor, "clientExecutor");
        this.swingExecutor = Objects.requireNonNull(swingExecutor, "swingExecutor");
    }

    static ThreadBridge runtime(ClientThread clientThread)
    {
        Objects.requireNonNull(clientThread, "clientThread");
        return new ThreadBridge(clientThread::invoke, SwingUtilities::invokeLater);
    }

    void submitClient(Runnable command)
    {
        if (command != null)
        {
            clientExecutor.accept(command);
        }
    }

    void submitSwing(Runnable render)
    {
        if (render != null)
        {
            swingExecutor.accept(render);
        }
    }
}

