	private static String matchSummary(int count)
	{
		return count == 1 ? "1 match" : count + " matches";
	}

	private static String observedSummary(int count)
	{
		return count == 1 ? "1 observed item" : count + " observed items";
	}

	private static JLabel detailLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(label.getFont().deriveFont(11f));
		return label;
	}

	private static JTextArea wrappedText(String body)
	{
		JTextArea text = new JTextArea(body == null ? "" : body);
		text.setLineWrap(true);
		text.setWrapStyleWord(true);
		text.setEditable(false);
		text.setFocusable(false);
		text.setOpaque(false);
		text.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return text;
	}

	private static String details(SemanticSearchResult result)
	{
		String source = result.getSourceName().isEmpty()
			? result.getSourceType().name()
			: result.getSourceName();
		String highlightState = result.isHighlightable() ? "highlightable" : "not highlightable";
		return "Source " + source
			+ " | Quantity " + result.getQuantity()
			+ " | " + highlightState;
	}

	private static String indexedDetails(ObservedItem item)
	{
		String source = item.getSourceName().isEmpty()
			? item.getSourceType().name()
			: item.getSourceName();
		String highlightState = item.isCurrentlyVisible() && item.getSourceType() == StorageSourceType.BANK
			? "visible in bank"
			: "remembered";
		return "Source " + source
			+ " | Quantity " + item.getQuantity()
			+ " | " + highlightState;
	}

	private static String coverageDetails(SemanticCoverageResult result)
	{
		String source = result.getSourceName().isEmpty()
			? result.getSourceType().name()
			: result.getSourceName();
		String highlightState = result.isCurrentlyVisible() && result.getSourceType() == StorageSourceType.BANK
			? "visible in bank"
			: "remembered";
		String categories = joinLimited(result.getCategories(), 3);
		String coverage;
		if (!categories.isEmpty())
		{
			coverage = " | Categories " + categories;
		}
		else if (!result.getMechanicalTags().isEmpty())
		{
			coverage = " | Mechanically known";
		}
		else if (result.getAwarenessStatus() == ItemAwarenessStatus.UNKNOWN_OBSERVED)
		{
			coverage = " | Unknown observed item";
		}
		else
		{
			coverage = " | Known unclassified";
		}
		return "Source " + source
			+ " | Quantity " + result.getQuantity()
			+ " | " + highlightState
			+ coverage;
	}

	private static String readinessDetails(ReadinessSlotResult slotResult)
	{
		String state = slotResult.isMissing() ? "missing" : "owned";
		return kindLabel(slotResult.getKind()) + " | " + state;
	}

	private static String kindLabel(ReadinessSlotKind kind)
	{
		if (kind == ReadinessSlotKind.REQUIRED)
		{
			return "Required";
		}
		if (kind == ReadinessSlotKind.OPTIONAL)
		{
			return "Optional";
		}
		if (kind == ReadinessSlotKind.UPGRADE)
		{
			return "Upgrade";
		}
		return "Recommended";
	}

	private static String readinessItems(List<SemanticSearchResult> items)
	{
		List<String> names = new ArrayList<>();
		for (SemanticSearchResult item : items)
		{
			String source = item.getSourceName().isEmpty()
				? item.getSourceType().name()
				: item.getSourceName();
			names.add(item.getItemName() + " x" + item.getQuantity() + " (" + source + ")");
		}
		return String.join(", ", names);
	}
	private static String joinLimited(List<String> values, int limit)
	{
		if (values == null || values.isEmpty() || limit <= 0)
		{
			return "";
		}

		List<String> joinedValues = new ArrayList<>();
		int remaining = 0;
		for (String value : values)
		{
			if (value == null || value.trim().isEmpty())
			{
				continue;
			}

			if (joinedValues.size() < limit)
			{
				joinedValues.add(value.trim());
			}
			else
			{
				remaining++;
			}
		}

		String joined = String.join(", ", joinedValues);
		if (remaining > 0)
		{
			return joined + ", +" + remaining + " more";
		}
		return joined;
	}
}

package com.semanticbanksearch;

import java.util.Set;
import net.runelite.api.EquipmentInventorySlot;

final class EquipmentSemanticClassifier
{
    private enum QueryType
    {
        NONE,
        WEAPON,
        ARMOUR,
        EQUIPMENT,
        MELEE_GEAR,
        RANGED_GEAR,
        MAGIC_GEAR,
        PRAYER_GEAR
    }

    private static final Set<String> WEAPON_QUERIES = Set.of(
        "weapon", "weapons", "weaponry", "wep", "weps", "wepon", "wepons", "weapn", "weapns", "all weapons");
    private static final Set<String> ARMOUR_QUERIES = Set.of(
        "armour", "armor", "armours", "armors", "armour gear", "armor gear", "all armour", "all armor");
    private static final Set<String> EQUIPMENT_QUERIES = Set.of(
        "gear", "equipment", "equipable", "equippable", "all gear", "all equipment");
    private static final Set<String> MELEE_QUERIES = Set.of(
        "melee gear", "melee equipment", "melee weapon", "melee weapons", "melee wep", "melee weps");
    private static final Set<String> RANGED_QUERIES = Set.of(
        "range gear", "ranged gear", "range equipment", "ranged equipment");
    private static final Set<String> MAGIC_QUERIES = Set.of(
        "mage gear", "magic gear", "mage equipment", "magic equipment");
    private static final Set<String> PRAYER_QUERIES = Set.of(
        "prayer gear", "prayer equipment", "prayer bonus", "prayer items");

    boolean recognizes(String query)
    {
        return queryType(query) != QueryType.NONE;
    }

    boolean matches(String query, BankItemMetadata item)
    {
        if (item == null)
        {
            return false;
        }

        switch (queryType(query))
        {
            case WEAPON:
                return isWeapon(item);
            case ARMOUR:
                return isArmour(item);
            case EQUIPMENT:
                return item.isEquipable();
            case MELEE_GEAR:
                return item.isEquipable() && item.meleeScore() > Math.max(item.rangedScore(), item.magicScore());
            case RANGED_GEAR:
                return item.isEquipable() && item.rangedScore() > Math.max(item.meleeScore(), item.magicScore());
            case MAGIC_GEAR:
                return item.isEquipable() && item.magicScore() > Math.max(item.meleeScore(), item.rangedScore());
            case PRAYER_GEAR:
                return item.isEquipable() && item.getPrayer() > 0;
            default:
                return false;
        }
    }

    private static boolean isWeapon(BankItemMetadata item)
    {
        return item.getEquipmentSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx() || item.isWieldable();
    }

    private static boolean isArmour(BankItemMetadata item)
    {
        if (!item.isEquipable())
        {
            return false;
        }

        int slot = item.getEquipmentSlot();
        return slot != EquipmentInventorySlot.WEAPON.getSlotIdx()
            && slot != EquipmentInventorySlot.AMMO.getSlotIdx()
            && slot != EquipmentInventorySlot.RING.getSlotIdx()
            && slot != EquipmentInventorySlot.AMULET.getSlotIdx();
    }

    private static QueryType queryType(String query)
    {
        String normalized = SemanticSearchEngine.normalize(query);
        if (WEAPON_QUERIES.contains(normalized))
        {
            return QueryType.WEAPON;
        }
        if (ARMOUR_QUERIES.contains(normalized))
        {
            return QueryType.ARMOUR;
        }
        if (EQUIPMENT_QUERIES.contains(normalized))
        {
            return QueryType.EQUIPMENT;
        }
        if (MELEE_QUERIES.contains(normalized))
        {
            return QueryType.MELEE_GEAR;
        }
        if (RANGED_QUERIES.contains(normalized))
        {
            return QueryType.RANGED_GEAR;
        }
        if (MAGIC_QUERIES.contains(normalized))
        {
            return QueryType.MAGIC_GEAR;
        }
        if (PRAYER_QUERIES.contains(normalized))
        {
            return QueryType.PRAYER_GEAR;
        }
        return QueryType.NONE;
    }
}

package com.semanticbanksearch;

import java.util.function.IntFunction;

class SemanticBankSearchStorage
{
    private SemanticBankSearchStorage() { }

    static AccountStorageDocument toDocument(StorageIndex index)
    {
        AccountStorageDocument document = new AccountStorageDocument();
        document.schemaVersion = AccountStorageRepository.SCHEMA_VERSION;
        document.catalogueVersion = AccountStorageRepository.CURRENT_CATALOGUE_VERSION;
        if (index != null)
        {
            for (ObservedItem item : index.items())
            {
                document.items.add(StoredObservedItem.from(item));
            }
        }
        return document;
    }

    static StorageIndex toIndex(AccountStorageDocument document, IntFunction<String> itemNameResolver)
    {
        StorageIndex index = new StorageIndex();
        if (document == null || !document.isSupported()) return index;
        for (StoredObservedItem item : document.items)
        {
            if (item == null || item.itemId <= 0) continue;
            String name = resolveName(item.itemId, itemNameResolver);
            index.record(item.itemId, name, Math.max(0, item.quantity), ObservedItem.normalizeSourceType(item.sourceType), item.sourceName == null ? "" : item.sourceName, item.currentlyVisible, Math.max(0L, item.lastSeenMillis));
        }
        return index;
    }

    private static String resolveName(int itemId, IntFunction<String> itemNameResolver)
    {
        try
        {
            String name = itemNameResolver == null ? null : itemNameResolver.apply(itemId);
            if (name != null && !name.trim().isEmpty()) return name.trim();
        }
        catch (RuntimeException ex)
        {
            // The persisted observation remains usable while item metadata is unavailable.
        }
        return "Item " + itemId;
    }
}

package com.semanticbanksearch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class PanelViewSnapshot
{
    enum Kind
    {
        CLEAR,
        SEARCH,
        ALL_INDEXED,
        READINESS,
        COVERAGE_AUDIT
    }

    private final long revision;
    private final Kind kind;
    private final String query;
    private final String status;
    private final List<SemanticSearchResult> searchResults;
    private final List<ObservedItem> indexedItems;
    private final ReadinessResult readinessResult;
    private final List<SemanticCoverageResult> coverageResults;

    private PanelViewSnapshot(
        long revision,
        Kind kind,
        String query,
        String status,
        List<SemanticSearchResult> searchResults,
        List<ObservedItem> indexedItems,
        ReadinessResult readinessResult,
        List<SemanticCoverageResult> coverageResults)
    {
        this.revision = revision;
        this.kind = kind;
        this.query = clean(query);
        this.status = clean(status);
        this.searchResults = immutableCopy(searchResults);
        this.indexedItems = immutableObservedItemCopy(indexedItems);
        this.readinessResult = readinessResult;
        this.coverageResults = immutableCopy(coverageResults);
    }

    static PanelViewSnapshot clear(long revision)
    {
        return clear(revision, "");
    }

    static PanelViewSnapshot clear(long revision, String status)
    {
        return new PanelViewSnapshot(
            revision,
            Kind.CLEAR,
            "",
            status,
            Collections.emptyList(),
            Collections.emptyList(),
            null,
            Collections.emptyList());
    }

    static PanelViewSnapshot search(
        long revision,
        String query,
        List<SemanticSearchResult> results,
        String status)
    {
        return new PanelViewSnapshot(
            revision,
            Kind.SEARCH,
            query,
            status,
            results,
            Collections.emptyList(),
            null,
            Collections.emptyList());
    }

    static PanelViewSnapshot allIndexed(long revision, List<ObservedItem> items, String status)
    {
        return new PanelViewSnapshot(
            revision,
            Kind.ALL_INDEXED,
            "",
            status,
            Collections.emptyList(),
            items,
            null,
            Collections.emptyList());
    }

    static PanelViewSnapshot readiness(
        long revision,
        String query,
        ReadinessResult result,
        String status)
    {
        return new PanelViewSnapshot(
            revision,
            Kind.READINESS,
            query,
            status,
            Collections.emptyList(),
            Collections.emptyList(),
            result == null ? ReadinessResult.unmatched(query) : result,
            Collections.emptyList());
    }

    static PanelViewSnapshot coverageAudit(
        long revision,
        List<SemanticCoverageResult> results,
        String status)
    {
        return new PanelViewSnapshot(
            revision,
            Kind.COVERAGE_AUDIT,
            "",
            status,
            Collections.emptyList(),
            Collections.emptyList(),
            null,
            results);
    }

    long getRevision()
    {
        return revision;
    }

    Kind getKind()
    {
        return kind;
    }

    String getQuery()
    {
        return query;
    }

    String getStatus()
    {
        return status;
    }

    List<SemanticSearchResult> getSearchResults()
    {
        return searchResults;
    }

    List<ObservedItem> getIndexedItems()
    {
        return indexedItems;
    }

    ReadinessResult getReadinessResult()
    {
        return readinessResult;
    }

    List<SemanticCoverageResult> getCoverageResults()
    {
        return coverageResults;
    }

    private static <T> List<T> immutableCopy(List<T> values)
    {
        if (values == null || values.isEmpty())
        {
            return Collections.emptyList();
        }
        return Collections.unmodifiableList(new ArrayList<>(values));
    }

    private static List<ObservedItem> immutableObservedItemCopy(List<ObservedItem> items)
    {
        if (items == null || items.isEmpty())
        {
            return Collections.emptyList();
        }

        List<ObservedItem> copiedItems = new ArrayList<>();
        for (ObservedItem item : items)
        {
            if (item != null)
            {
                copiedItems.add(new ObservedItem(item));
            }
        }
        return copiedItems.isEmpty()
            ? Collections.emptyList()
            : Collections.unmodifiableList(copiedItems);
    }

    private static String clean(String value)
    {
        return value == null ? "" : value.trim();
    }
}

package com.semanticbanksearch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.Supplier;

class SemanticBankFilter
{
    static final String FORCE_PREFIX = "sem ";

    private final SemanticSearchEngine engine;
    private final IntFunction<BankItemMetadata> itemMetadataProvider;
    private final Supplier<List<Integer>> ownedItemIdsProvider;
    private final EquipmentSemanticClassifier equipmentClassifier = new EquipmentSemanticClassifier();
    private final ConsumableSemanticClassifier consumableClassifier = new ConsumableSemanticClassifier();
    private final NumericSemanticClassifier numericClassifier = new NumericSemanticClassifier();
    private final RelativeRankingClassifier rankingClassifier = new RelativeRankingClassifier();
    private final SemanticBankQueryParser queryParser = new SemanticBankQueryParser();
    private final Map<Integer, Boolean> decisions = new HashMap<>();
    private final Map<Integer, BankItemMetadata> metadataCache = new HashMap<>();
    private String cachedInput = "";
    private String cachedQuery = "";
    private List<String> cachedClauses = Collections.emptyList();
    private List<BankItemMetadata> cachedOwnedItems = Collections.emptyList();
    private boolean cachedSemanticSearch;

    SemanticBankFilter(SemanticSearchEngine engine, IntFunction<BankItemMetadata> itemMetadataProvider)
    {
        this(engine, itemMetadataProvider, Collections::emptyList);
    }

    SemanticBankFilter(
        SemanticSearchEngine engine,
        IntFunction<BankItemMetadata> itemMetadataProvider,
        Supplier<List<Integer>> ownedItemIdsProvider)
    {
        this.engine = engine;
        this.itemMetadataProvider = itemMetadataProvider;
        this.ownedItemIdsProvider = ownedItemIdsProvider == null ? Collections::emptyList : ownedItemIdsProvider;
    }

    Boolean decision(String input, int itemId)
    {
        String normalizedInput = SemanticSearchEngine.normalize(input);
        if (!normalizedInput.equals(cachedInput))
        {
            prepare(normalizedInput);
        }

        if (!cachedSemanticSearch)
        {
            return null;
        }
        if (itemId == -1)
        {
            return null;
        }

        return decisions.computeIfAbsent(itemId, id ->
        {
            BankItemMetadata item = metadataFor(id);
            if (!cachedClauses.isEmpty())
            {
                for (String clause : cachedClauses)
                {
                    if (!matchesClause(clause, item))
                    {
                        return false;
                    }
                }
                return true;
            }
            return matchesClause(cachedQuery, item);
        });
    }

    String semanticQuery(String input)
    {
        String normalizedInput = SemanticSearchEngine.normalize(input);
        if (normalizedInput.startsWith(FORCE_PREFIX))
        {
            return normalizedInput.substring(FORCE_PREFIX.length()).trim();
        }
        if (!queryParser.parse(normalizedInput).isEmpty())
        {
            return normalizedInput;
        }
        return equipmentClassifier.recognizes(normalizedInput)
            || consumableClassifier.recognizes(normalizedInput)
            || numericClassifier.recognizes(normalizedInput)
            || rankingClassifier.recognizes(normalizedInput)
            || engine.hasSemanticMatch(normalizedInput)
            ? normalizedInput
            : "";
    }

    private void prepare(String normalizedInput)
    {
        metadataCache.clear();
        cachedInput = normalizedInput;
        cachedQuery = semanticQuery(normalizedInput);
        cachedClauses = queryParser.parse(cachedQuery);
        cachedOwnedItems = rankingClassifier.recognizes(cachedQuery) ? loadOwnedItems() : Collections.emptyList();
        cachedSemanticSearch = !cachedQuery.isEmpty()
            && (normalizedInput.startsWith(FORCE_PREFIX)
                || !cachedClauses.isEmpty()
                || equipmentClassifier.recognizes(cachedQuery)
                || consumableClassifier.recognizes(cachedQuery)
                || numericClassifier.recognizes(cachedQuery)
                || rankingClassifier.recognizes(cachedQuery)
                || engine.hasSemanticMatch(cachedQuery));
        decisions.clear();
    }

    private boolean matchesClause(String clause, BankItemMetadata item)
    {
        if (numericClassifier.recognizes(clause))
        {
            return numericClassifier.matches(clause, item);
        }
        if (rankingClassifier.recognizes(clause))
        {
            return rankingClassifier.matches(clause, item, cachedOwnedItems);
        }

        return equipmentClassifier.matches(clause, item)
            || consumableClassifier.matches(clause, item)
            || engine.matchesPurpose(clause, item == null ? "" : item.getName());
    }

    private List<BankItemMetadata> loadOwnedItems()
    {
        List<BankItemMetadata> items = new ArrayList<>();
        for (Integer itemId : ownedItemIdsProvider.get())
        {
            if (itemId != null && itemId > 0)
            {
                BankItemMetadata item = metadataFor(itemId);
                if (item != null)
                {
                    items.add(item);
                }
            }
        }
        return items;
    }

    private BankItemMetadata metadataFor(int itemId)
    {
        return metadataCache.computeIfAbsent(itemId, itemMetadataProvider::apply);
    }
}

